{
  "done": false,
  "tool": "manage_backends",
  "args": {
    "operation": "add",
    "apps_json": [
      {
        "name": "Evidence Hub",
        "description": "Evidence, notes, and alert posture.",
        "tabs": {
          "evidence": {
            "id": "evidence",
            "name": "Evidence",
            "layout": [
              {
                "i": "evidence_files",
                "x": 0,
                "y": 0,
                "w": 20,
                "h": 14
              },
              {
                "i": "alert_metric",
                "x": 20,
                "y": 0,
                "w": 6,
                "h": 4
              }
            ]
          },
          "notes": {
            "id": "notes",
            "name": "Notes",
            "layout": [
              {
                "i": "case_notes",
                "x": 0,
                "y": 0,
                "w": 12,
                "h": 8
              }
            ]
          }
        },
        "groups": [
          {
            "name": "Evidence Sync",
            "type": "param",
            "paramName": "case_scope",
            "widgetIds": [
              "evidence_files",
              "case_notes"
            ]
          }
        ]
      }
    ],
    "widgets_json": {
      "evidence_files": {
        "name": "Evidence Files",
        "description": "Browse case evidence documents.",
        "endpoint": "/evidence-files",
        "type": "multi_file_viewer",
        "w": 20,
        "h": 14,
        "params": [
          {
            "paramName": "file",
            "type": "endpoint",
            "label": "File",
            "optionsEndpoint": "/evidence-file-options",
            "multiSelect": true,
            "default": []
          }
        ],
        "data": {
          "updateFrequency": 0
        }
      },
      "case_notes": {
        "name": "Case Notes",
        "description": "Notes for one surveillance case.",
        "endpoint": "/case-notes",
        "type": "markdown",
        "w": 12,
        "h": 8,
        "params": [
          {
            "paramName": "case_id",
            "type": "text",
            "label": "Case",
            "default": "C-1042",
            "description": "Case identifier."
          }
        ]
      },
      "alert_metric": {
        "name": "Open Alerts",
        "description": "Open alert count.",
        "endpoint": "/alert-count",
        "type": "metric",
        "w": 5,
        "h": 4,
        "params": []
      }
    }
  }
}

